    // 1. Initialize Winsock
    WSADATA wsa;
    WSAStartup(MAKEWORD(2,2), &wsa);

    // 2. Create socket
    SOCKET s = socket(AF_INET, SOCK_STREAM, 0);
    sockaddr_in server;
    server.sin_addr.s_addr = inet_addr("pool.example.com");
    server.sin_family = AF_INET;
    server.sin_port = htons(3333);

    // 3. Connect
    connect(s, (sockaddr*)&server, sizeof(server));

    // 4. Send mining job request (pseudo‑JSON)
    const char* job = "{\"method\":\"mining.subscribe\",\"params\":[],\"id\":1}\n";
    send(s, job, strlen(job), 0);

    // 5. Receive and parse job, then start mining loop
    // (actual mining code omitted for brevity)

    // 6. Close socket
    closesocket(s);
    WSACleanup();
    return 0;
}
```

